html:
{% set exact_gl = frappe.get_all("Bank Cheque Layout", filters={"bank_account_gl": doc.bank_account}, limit=1) if doc.bank_account else [] %}
{% if exact_gl %}
  {% set layout = frappe.get_doc("Bank Cheque Layout", exact_gl[0].name) %}
{% else %}
  {% set bank_key = (doc.cheque_bank or doc.bank_account or "") %}
  {% set bank_clean = bank_key.replace("PLC", "").replace("Limited", "").split("-")[0].strip() %}
  {% set matched_by_id = frappe.get_all("Bank Cheque Layout", filters={"name": ["like", "%" + bank_clean + "%"]}, limit=1) if bank_clean else [] %}
  {% set matched_by_field = frappe.get_all("Bank Cheque Layout", filters={"bank_name": ["like", "%" + bank_clean + "%"]}, limit=1) if bank_clean else [] %}
  {% if matched_by_id %}
    {% set layout = frappe.get_doc("Bank Cheque Layout", matched_by_id[0].name) %}
  {% elif matched_by_field %}
    {% set layout = frappe.get_doc("Bank Cheque Layout", matched_by_field[0].name) %}
  {% else %}
    {% set def_layout = frappe.get_all("Bank Cheque Layout", filters={"is_default": 1}, limit=1) %}
    {% set layout = frappe.get_doc("Bank Cheque Layout", def_layout[0].name) if def_layout else frappe._dict() %}
  {% endif %}
{% endif %}

{% set d_str = frappe.utils.formatdate(doc.cheque_date, "ddMMyyyy") %}
{% set raw_words = frappe.utils.money_in_words(doc.amount or 0, "INR") %}
{% set words_clean = raw_words.replace("INR", "").replace("Rupees", "").replace("Rupee", "").replace("Paise", "Paisa").replace("only.", "").replace("Only.", "").strip() + " Taka Only" %}

<style>
  .print-format-gutter,
  .print-format {
    padding: 0 !important;
    margin: 0 !important;
    max-width: none !important;
    width: 100% !important;
  }
  .cheque-preview-wrapper *,
  .cheque-canvas,
  .cheque-canvas * {
    box-sizing: border-box !important;
  }

  @media screen {
    .cheque-preview-wrapper {
      padding: 20px;
      background: #f1f5f9;
      display: flex;
      flex-direction: column;
      align-items: center;
      overflow-x: auto;
    }
    .preview-badge {
      background: #0f172a;
      color: #f8fafc;
      font-size: 11px;
      padding: 5px 14px;
      border-radius: 20px;
      margin-bottom: 12px;
      font-family: sans-serif;
    }
    .cheque-canvas {
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);
      border: 1px solid #64748b;
      background-color: #eef6f9;
    }
    .cheque-bg-img {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      object-fit: fill;
      z-index: 1;
      pointer-events: none;
    }
  }

  @media print {
    @page {
      size: {{ layout.page_width_mm or 195 }}mm {{ layout.page_height_mm or 85 }}mm;
      margin: 0 !important;
    }
    html, body, .print-format, .cheque-preview-wrapper {
      margin: 0 !important;
      padding: 0 !important;
      background: transparent !important;
    }
    .preview-badge, .cheque-guides, .cheque-bg-img {
      display: none !important;
    }
    .cheque-canvas {
      background: transparent !important;
      border: none !important;
      box-shadow: none !important;
    }
  }

  .cheque-canvas {
    position: relative;
    width: {{ layout.page_width_mm or 195 }}mm !important;
    min-width: {{ layout.page_width_mm or 195 }}mm !important;
    max-width: {{ layout.page_width_mm or 195 }}mm !important;
    height: {{ layout.page_height_mm or 85 }}mm !important;
    min-height: {{ layout.page_height_mm or 85 }}mm !important;
    max-height: {{ layout.page_height_mm or 85 }}mm !important;
    font-family: 'Courier New', Courier, monospace !important;
    font-weight: bold !important;
    color: #000000 !important;
    overflow: hidden;
    text-align: left;
    zoom: 1 !important;
    transform: none !important;
  }
  .cheque-field {
    position: absolute;
    z-index: 5;
    margin: 0 !important;
    padding: 0 !important;
    line-height: 1.42857 !important;
  }
  .ac-payee-stamp {
    top: {{ layout.ac_payee_top_mm or 12 }}mm;
    left: {{ layout.ac_payee_left_mm or 14 }}mm;
    border-top: 1.5px solid #000;
    border-bottom: 1.5px solid #000;
    width: 58mm;
    text-align: center;
    padding: 1.5px 0 !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9.5px;
    letter-spacing: 1.2px;
    transform: rotate(-38deg);
    white-space: nowrap;
  }
  .cheque-date {
    top: {{ layout.date_top_mm or 11 }}mm;
    left: {{ layout.date_left_mm or 144 }}mm;
    font-size: {{ layout.date_font_size or 14 }}px;
    letter-spacing: {{ layout.date_letter_spacing_mm or 3.4 }}mm;
  }
  .cheque-payee {
    top: {{ layout.payee_top_mm or 24 }}mm;
    left: {{ layout.payee_left_mm or 24 }}mm;
    width: {{ layout.payee_width_mm or 145 }}mm;
    font-size: {{ layout.payee_font_size or 13 }}px;
    white-space: nowrap;
    overflow: hidden;
  }
  .cheque-words {
    top: {{ layout.words_top_mm or 34 }}mm;
    left: {{ layout.words_left_mm or 32 }}mm;
    width: {{ layout.words_width_mm or 102 }}mm;
    line-height: {{ layout.words_line_height_mm or 8.5 }}mm !important;
    font-size: {{ layout.words_font_size or 12 }}px;
    word-wrap: break-word;
  }
  .cheque-amount {
    top: {{ layout.amount_top_mm or 36 }}mm;
    left: {{ layout.amount_left_mm or 146 }}mm;
    font-size: {{ layout.amount_font_size or 14 }}px;
  }
</style>

<div class="cheque-preview-wrapper">
  <div class="preview-badge">
    Active Layout: {{ layout.name or layout.bank_name or "Standard BD Cheque" }} ({{ layout.page_width_mm }}mm x {{ layout.page_height_mm }}mm)
  </div>

  <div class="cheque-canvas">
    {% if layout.cheque_sample_image %}
      <img class="cheque-bg-img" src="{{ layout.cheque_sample_image }}" alt="Cheque Background" />
    {% endif %}

    {% if doc.is_account_payee %}
      <div class="cheque-field ac-payee-stamp">A/C PAYEE ONLY</div>
    {% endif %}

    <div class="cheque-field cheque-date">{{ d_str }}</div>
    <div class="cheque-field cheque-payee">**{{ (doc.party_name or doc.party or '').strip() }}**</div>
    <div class="cheque-field cheque-words">**{{ words_clean.strip() }}**</div>
    <div class="cheque-field cheque-amount">**{{"{:,.2f}".format(doc.amount or 0)}}/=</div>
  </div>
</div>
